package com.example.expenses;

import java.math.BigDecimal;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;

/** Calls GET /rates/{currency}; expects {"rate": 1.08}, meaning 1 unit of currency = rate EUR. */
@Component
public class ExchangeRateClient {
    record RateResponse(BigDecimal rate) {}

    private final RestClient client;

    public ExchangeRateClient(@Value("${exchange-rate.base-url}") String baseUrl) {
        this.client = RestClient.builder().baseUrl(baseUrl).build();
    }

    public BigDecimal rateToEur(String currency) {
        RateResponse r = client.get().uri("/rates/{c}", currency).retrieve().body(RateResponse.class);
        if (r == null || r.rate() == null || r.rate().signum() <= 0) {
            throw new IllegalStateException("Invalid rate for " + currency);
        }
        return r.rate();
    }
}
