package com.example.expenses;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import org.springframework.stereotype.Service;

@Service
public class ClaimService {
    static final BigDecimal APPROVAL_THRESHOLD_EUR = new BigDecimal("1000");

    private final ExchangeRateClient rates;
    private final Map<UUID, Claim> claims = new ConcurrentHashMap<>();

    public ClaimService(ExchangeRateClient rates) {
        this.rates = rates;
    }

    public Claim submit(ClaimRequest req) {
        String currency = req.currency().toUpperCase();
        BigDecimal rate = currency.equals("EUR") ? BigDecimal.ONE : rates.rateToEur(currency);
        BigDecimal eur = req.amount().multiply(rate).setScale(2, RoundingMode.HALF_UP);
        ClaimStatus status = eur.compareTo(APPROVAL_THRESHOLD_EUR) > 0
                ? ClaimStatus.PENDING_APPROVAL : ClaimStatus.APPROVED;
        Claim claim = new Claim(UUID.randomUUID(), req.employeeId(), req.amount(), currency, eur, status);
        claims.put(claim.id(), claim);
        return claim;
    }
}
